def reference(x, y):
    """Obviously correct model: biggest even integer k with x <= k <= y, else -1."""
    if x > y:
        return -1
    hi = math.floor(y)
    if hi % 2 != 0:
        hi -= 1
    if hi < x:
        return -1
    return hi

@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_property_result_is_even_in_range_or_minus_one(x, y):
    # normalize to x <= y for range property; other direction covered above
    assume(x <= y)
    r = choose_num(x, y)
    if r == -1:
        # for integer positive inputs, -1 is only valid if no even in range
        evens = [k for k in range(x, y + 1) if k % 2 == 0]
        assert evens == []
    else:
        assert isinstance(r, int)
        assert r % 2 == 0
        assert x <= r <= y
